/** Build-only: exact defaults generated by the already-verified official CLI.
 * Never invoked at runtime or on document input. No JAR/profile modification.
 */
import { constants } from 'node:fs';
import { open, lstat, realpath, mkdir, writeFile, chmod } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import path from 'node:path';
import { VERAPDF_CLI_SHA256 } from '../own-invoice-pdfa/runtime-notices.mjs';
export const CONFIG_NAMES=['app.xml','features.xml','fixer.xml','plugins.xml','validator.xml'];
export const LOGGING_PROPERTIES='# Foreign-only runtime logging; PDF/A validation defaults are unchanged.\nhandlers=\n.level=OFF\n';
const digest=bytes=>createHash('sha256').update(bytes).digest('hex');
export async function prepareVerifierConfigAssets(destination,asset,defaults){
  if(!path.isAbsolute(destination)||!path.isAbsolute(defaults)||await realpath(defaults)!==defaults)throw Error('Official default configuration unavailable');
  const root=path.join(destination,'foreign-runtime'),templates=[];
  for(const name of CONFIG_NAMES){
    const file=path.join(defaults,name),info=await lstat(file);
    if(await realpath(file)!==file)throw Error('Official default configuration unavailable');
    if(!info.isFile()||info.isSymbolicLink()||info.nlink!==1||info.size<1||info.size>64*1024)throw Error('Official default configuration unavailable');
    const handle=await open(file,constants.O_RDONLY|constants.O_NOFOLLOW);let value;
    try{const stat=await handle.stat();if(!stat.isFile()||stat.nlink!==1||stat.size!==info.size)throw Error('Official default configuration unavailable');const buffer=Buffer.alloc(64*1024+1),read=await handle.read(buffer,0,buffer.length,0);if(read.bytesRead!==stat.size)throw Error('Official default configuration unavailable');value=buffer.subarray(0,read.bytesRead);}finally{await handle.close();}
    templates.push({name,value,bytes:value.length,sha256:digest(value)});
  }
  await mkdir(root,{mode:0o755});await mkdir(path.join(root,'templates'),{mode:0o755});
  await mkdir(path.join(root,'classes/org/verapdf/processor'),{recursive:true,mode:0o755});
  for(const entry of templates){const file=path.join(root,'templates',entry.name);await writeFile(file,entry.value,{flag:'wx',mode:0o444});await chmod(file,0o444);}
  const logging=Buffer.from(LOGGING_PROPERTIES),logFile=path.join(root,'classes/org/verapdf/processor/logging.properties');
  await writeFile(logFile,logging,{flag:'wx',mode:0o444});await chmod(logFile,0o444);
  const evidence={schema:1,version:asset.version,sourceArchiveSha256:asset.sha256,cliSha256:VERAPDF_CLI_SHA256,generatedBy:'official-cli-version-build-only',templates:templates.map(({name,bytes,sha256})=>({name,bytes,sha256})),logging:{bytes:logging.length,sha256:digest(logging)}};
  const manifest=path.join(root,'manifest.json');await writeFile(manifest,JSON.stringify(evidence,null,2)+'\n',{flag:'wx',mode:0o444});await chmod(manifest,0o444);
  return evidence;
}
